def transform(grid):
    """Extend diagonals that contain at least two matching non-background cells."""
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    points = {}
    for r in range(h):
        for c in range(w):
            if original[r][c] != bg:
                points.setdefault(original[r][c], []).append((r, c))
    for color, cells in points.items():
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) != abs(dc):
                    continue
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                # Extend the line from each endpoint; other colors stop the ray.
                for r, c, step in ((r1, c1, -1), (r2, c2, 1)):
                    rr, cc = r + step*sr, c + step*sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if original[rr][cc] != bg:
                            break
                        out[rr][cc] = color
                        rr += step*sr
                        cc += step*sc
    return out
